class KadriWorkPage(ft.Column):
    def _wrap_control(self, control):
        """Возвращает контрол для показа: внутри каркаса — через shell
        (боковое меню сохраняется), автономно — как раньше."""
        from pages import shell as _shell
        sh = _shell.get_shell()
        if sh is not None and self._page is not None:
            sh.open_standalone(type(control).__name__, control)
            return None
        return control

    def __init__(self, page, parent=None):
        super().__init__(scroll=ft.ScrollMode.AUTO)
        if page is None:
            raise ValueError("Page is null")
        self._page = page
        self.add_student_button = ft.FilledButton("Добавить курсанта", width=300, on_click=self.add_student_click)
        self.show_students_button = ft.FilledButton("Показать курсанта", width=300, on_click=self.show_students_click)
        self.change_position_button = ft.FilledButton("Изменить должность", width=300, on_click=self.go_to_position_change_page)
        self.change_rank_button = ft.FilledButton("Изменить звание", width=300, on_click=self.go_to_rank_change_page)
        self.back_button = ft.FilledButton("Назад", on_click=self.back_click)

        if self.add_student_button is None:
            raise ValueError("Add student button is null")
        if self.show_students_button is None:
            raise ValueError("Show students button is null")
        if self.back_button is None:
            raise ValueError("Back button is null")

        self.controls = [
            ft.Text("Кадровая работа", size=20, weight="bold"),
            self.add_student_button,
            self.show_students_button,
            self.change_position_button,
            self.change_rank_button,
            self.back_button
        ]

    # Обработчик нажатия кнопки "Добавить курсанта"
    def add_student_click(self, e):
        shell.navigate(self._page, "AddStudentPage")

    # Обработчик нажатия кнопки "Показать курсанта"
    def show_students_click(self, e):
        shell.navigate(self._page, "ShowStudentsPage")

    # Обработчик нажатия кнопки "Изменить должность"
    def go_to_position_change_page(self, e):
        shell.navigate(self._page, "PositionChangePage")

    # Обработчик нажатия кнопки "Изменить звание"
    def go_to_rank_change_page(self, e):
        shell.navigate(self._page, "RankChangePage")
        
    # Обработчик нажатия кнопки "Назад"
    def _wrap_control(self, control):
        """Возвращает контрол для показа: внутри каркаса — через shell
        (боковое меню сохраняется), автономно — как раньше."""
        from pages import shell as _shell
        sh = _shell.get_shell()
        if sh is not None and self._page is not None:
            sh.open_standalone(type(control).__name__, control)
            return None
        return control

    def back_click(self, e):
        shell.back_to_app(self._page)

DEFAULT_PHOTO_BASE64 = ""

class AddStudentPage(ft.Column):
    def __init__(self, page, parent=None):
        super().__init__(scroll=ft.ScrollMode.AUTO)
        self._page = page

        # --- Реестр текстовых полей формы (декомпозиция god-класса) ----------
        # Поля объявляются в конце __init__ (_build_fields) через self._tf(),
        # который создаёт ft.TextField, привязывает его к атрибуту и регистрирует
        # имя в _field_names. Благодаря этому save_click собирает данные и
        # очищает форму рефлексивно, без ручных словарей на ~100 строк.
        self._field_names: list[str] = []

        self.back_button = ft.FilledButton("Назад", on_click=self.back_click)
        self.save_button = ft.FilledButton("Сохранить", on_click=self.save_click)

        # --- Фотографии курсантов -------------------------------------------
        # Загруженные фото хранятся в файловом хранилище DATA_DIR/photos
        # (см. app/photo_storage.py), а в колонке students.o_photo лежит
        # относительное имя файла. Раньше base64 писался прямо в БД — из-за
        # этого база раздувалась и строились огромные Row-объекты.
        # photo_base64 хранит ТЕКУЩЕЕ выбранное фото как data-URI (или None);
        # save_click сохраняет его через photo_storage.save_photo() и пишет
        # в student_data["o_photo"] имя файла.
        self.photo_base64 = None
        self.photo_picker = ft.FilePicker(on_result=self.handle_photo_upload)
        # Файловый диалог живёт в overlay страницы; добавляем ровно один раз
        # (страница может пересоздаваться при навигации).
        try:
            ov = list(self._page.overlay)
            if not any(isinstance(c, ft.FilePicker) for c in ov):
                self._page.overlay.append(self.photo_picker)
        except Exception:
            # overlay недоступен (не-рантайм страница) — диалог не критичен
            log_except("kadri_page: добавление FilePicker в overlay")

        self.photo_bytes: bytes | None = None  # байты выбранного фото (для сохранения на диске)
        self.photo_ext: str = "jpg"

        def _default_photo_src():
            """Заглушка по умолчанию из assets/ как data-URI (файл бинарный,
            не тащим ~1 МБ base64-литерал в код страницы)."""
            try:
                with open(os.path.join(os.path.dirname(photo_storage.__file__),
                                       os.pardir, "assets", "default_photo.jpg"), "rb") as f:
                    return "data:image/jpeg;base64," + base64.b64encode(f.read()).decode("ascii")
            except OSError:
                return ""

        self._default_photo_src = _default_photo_src()
        self.photo_preview = ft.Image(
            # В Flet >= 0.80 параметр src_base64 удалён: base64 передаётся
            # через src в формате data-URI; файлы-фото — локальным путём.
            src=self._default_photo_src,
            width=150,
            height=150,
            fit=ft.BoxFit.COVER,
            border_radius=10,
        )

        self.upload_photo_button = ft.FilledButton(
            "Загрузить фотографию",
            on_click=lambda _: self.photo_picker.pick_files(
                allow_multiple=False,
                allowed_extensions=["jpg", "jpeg", "png"],
            ),
        )

